const messages={reply:'Find the words, review your reply, then choose whether to archive.',delegate:'Choose a saved person, add a message, and review before forwarding.',snooze:'Let this conversation return at a moment that works better for you.',archive:'Keep the conversation in the archive of the account it came from.'};document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-action]').forEach(other=>other.setAttribute('aria-pressed',String(other===button)));document.getElementById('demo-note').textContent=messages[button.dataset.action]}));